#include <stdio.h>

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int health_uku = 2 * N;
    int health_ushi = 2 * M;
    int score = 0;

    while (1) {
        // Team UKU attacks Team Ushi
        int attacks_uku = N;
        while (attacks_uku > 0 && health_ushi > 0) {
            health_ushi--;
            attacks_uku--;
        }

        if (health_ushi <= 0) break;

        // After UKU attacks, if Ushi still has members, score increases
        score++;

        // Team Ushi attacks Team UKU
        int attacks_ushi = M;
        while (attacks_ushi > 0 && health_uku > 0) {
            health_uku--;
            attacks_ushi--;
        }

        if (health_uku <= 0) break;

        // After Ushi attacks, if UKU still has members, score increases
        score++;

        // Recalculate member counts from health
        N = (health_uku + 1) / 2;
        M = (health_ushi + 1) / 2;
    }

    printf("%d\n", score);
    return 0;
}

#include <stdio.h>

int main() {
    long long N, M;
    scanf("%lld %lld", &N, &M);

    long long score = 0;
    long long nu = N, mu = M; // current members
    long long wu = 0, ws = 0; // wounded in each team

    while (1) {
        // UKU attacks Ushi with nu attacks
        // ws wounded in Ushi, (mu - ws) healthy
        long long attacks = nu;
        long long kills = 0;
        // kill wounded first
        long long kw = (attacks < ws) ? attacks : ws;
        kills += kw; attacks -= kw; ws -= kw;
        // kill healthy
        long long kh = attacks / 2;
        kills += kh; 
        ws += attacks % 2; // new wounded
        attacks = 0;
        mu -= kills;
        if (mu <= 0) break;

        score++;

        // Ushi attacks UKU with mu attacks
        attacks = mu;
        kills = 0;
        long long kw2 = (attacks < wu) ? attacks : wu;
        kills += kw2; attacks -= kw2; wu -= kw2;
        long long kh2 = attacks / 2;
        kills += kh2;
        wu += attacks % 2;
        nu -= kills;
        if (nu <= 0) break;
    }

    printf("%lld\n", score);
    return 0;
}

