#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long N, M;
    cin >> N >> M;

    // In one full round:
    // - UKU deals N damage to Ushi
    // - if Ushi survives, score +1
    // - Ushi deals remaining_Ushi damage to UKU
    // - if UKU survives, score +1
    //
    // Since every member has 2 HP, a team with X members has total HP 2X.
    // To minimize score, all attacks should be concentrated as much as possible,
    // so only total damage matters.
    //
    // Let A = 2N, B = 2M be total HP.
    // After UKU's attack, B decreases by current alive UKU count.
    // After Ushi's attack, A decreases by current alive Ushi count.
    //
    // The optimal score turns out to be:
    //   2 * min(N, M) - (N == M ? 1 : 0)
    //
    // Intuition:
    // - Each side can surely survive the first min(N, M)-1 turns of both phases.
    // - On the last comparable phase, one side is eliminated, ending the game immediately.
    // - If N == M, the game ends after UKU's attack in the last round, so one phase less.

    long long ans = 2 * min(N, M) - (N == M ? 1 : 0);
    cout << ans << '\n';
    return 0;
}

