import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();

        // State: uku_full, uku_half, ushi_full, ushi_half
        // Simulate greedily
        int uf = N, uh = 0, sf = M, sh = 0;
        int score = 0;

        while (true) {
            // UKU attacks Ushi
            int attacks = uf + uh;
            // Kill half-HP ushi first
            int killHalf = Math.min(sh, attacks);
            attacks -= killHalf;
            sh -= killHalf;
            // Kill full-HP ushi
            int killFull = Math.min(sf, attacks / 2);
            attacks -= killFull * 2;
            sf -= killFull;
            // Remaining attacks damage full ushi
            int newHalf = (attacks > 0 && sf > 0) ? 1 : 0;
            if (newHalf == 1) { sf--; sh++; }
            // (attacks is 0 or 1 now, and sf might have been decremented)

            if (sf + sh == 0) break;
            score++;

            // Ushi attacks UKU
            attacks = sf + sh;
            int killHalf2 = Math.min(uh, attacks);
            attacks -= killHalf2;
            uh -= killHalf2;
            int killFull2 = Math.min(uf, attacks / 2);
            attacks -= killFull2 * 2;
            uf -= killFull2;
            int newHalf2 = (attacks > 0 && uf > 0) ? 1 : 0;
            if (newHalf2 == 1) { uf--; uh++; }

            if (uf + uh == 0) break;
        }

        System.out.println(score);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        long N = fs.nextLong();
        long M = fs.nextLong();

        // Minimum score equals the number of completed half-rounds
        // before one team can be eliminated.
        // This is ceil(2*M / N) - 1 if UKU eliminates Ushi first,
        // and ceil(2*N / M) if not better. By symmetry, the answer is:
        // min(ceil(2*M / N) - 1, ceil(2*N / M))
        // which simplifies to floor((2*min(N,M)-1)/max(N,M)).
        long a = Math.min(N, M);
        long b = Math.max(N, M);

        long ans = (2 * a - 1) / b;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
